input.content:
:root {
  color-scheme: dark;
  --ink: #e7eee8;
  --muted: #9daaa4;
  --panel: rgba(8, 15, 16, .78);
  --line: rgba(190, 218, 204, .18);
  --red: #e66c5f;
  --green: #81d99a;
  --gold: #d3b978;
  font-family: Inter, "Segoe UI", Arial, sans-serif;
  font-synthesis: none;
}
* { box-sizing: border-box; }
html, body { margin: 0; width: 100%; height: 100%; overflow: hidden; background: #10191b; color: var(--ink); overscroll-behavior: none; }
body { position: relative; user-select: none; -webkit-user-select: none; -webkit-tap-highlight-color: transparent; touch-action: none; }
#gameCanvas { position: fixed; inset: 0; display: block; width: 100%; height: 100%; cursor: crosshair; touch-action: none; }
#hud { position: fixed; inset: 0; z-index: 2; pointer-events: none; }
.topbar { position: absolute; inset: max(14px, env(safe-area-inset-top)) max(14px, env(safe-area-inset-right)) auto max(14px, env(safe-area-inset-left)); display: flex; align-items: flex-start; gap: 9px; }
.panel { background: var(--panel); border: 1px solid var(--line); border-radius: 9px; padding: 10px 12px; box-shadow: 0 8px 26px #0005; backdrop-filter: blur(7px); }
.vitals { width: clamp(150px, 23vw, 255px); }
.meter-label { display: flex; justify-content: space-between; align-items: center; margin-bottom: 5px; font-size: 10px; letter-spacing: .13em; color: var(--muted); }
.meter-label strong { color: var(--ink); font-size: 11px; }
.bar { height: 8px; overflow: hidden; border-radius: 8px; background: #ffffff19; }
#healthBar, #staminaBar { width: 100%; height: 100%; border-radius: inherit; transition: width .15s ease; }
#healthBar { background: linear-gradient(90deg, #6cc889, #dbbb69 70%, #e35e55); }
#staminaBar { background: linear-gradient(90deg, #69cbe0, #9bd8bd); }
.stamina-label { margin-top: 8px; }
.stats-panel, .weapon-panel { min-width: 90px; display: flex; flex-direction: column; gap: 5px; }
.stats-panel strong, .weapon-panel strong { font-size: 13px; letter-spacing: .06em; white-space: nowrap; }
.stats-panel span, .weapon-panel span { font-size: 10px; letter-spacing: .12em; color: var(--muted); white-space: nowrap; }
#minimap { width: 92px; height: 92px; margin-left: auto; border-radius: 50%; border: 1px solid #bdcfc644; background: #071010bb; }
.icon-button { pointer-events: auto; width: 40px; height: 40px; padding: 0; border-radius: 7px; color: var(--ink); background: #10191dcc; border: 1px solid var(--line); box-shadow: none; }
#crosshair { position: absolute; top: 50%; left: 50%; width: 20px; height: 20px; transform: translate(-50%, -50%); opacity: .8; }
#crosshair::before, #crosshair::after { content: ""; position: absolute; background: #eaf3e9; box-shadow: 0 0 5px #fff8; }
#crosshair::before { width: 2px; height: 18px; left: 9px; top: 1px; }
#crosshair::after { height: 2px; width: 18px; top: 9px; left: 1px; }
#crosshair i { position: absolute; inset: 8px; border-radius: 50%; background: #fff; }
#messageBox { position: absolute; top: 20%; left: 50%; transform: translateX(-50%); padding: 9px 18px; border: 1px solid #d5c28544; border-radius: 3px; background: #0a1111c9; color: var(--gold); font-size: 12px; font-weight: 700; letter-spacing: .13em; opacity: 0; transition: opacity .2s ease; white-space: nowrap; }
#messageBox.visible { opacity: 1; }
#controlsHint { position: absolute; left: 50%; bottom: max(14px, env(safe-area-inset-bottom)); transform: translateX(-50%); color: #c1ccc080; font-size: 10px; letter-spacing: .08em; white-space: nowrap; text-shadow: 0 2px 6px #000; }
#joystick { position: absolute; left: max(24px, env(safe-area-inset-left)); bottom: max(32px, env(safe-area-inset-bottom)); width: 132px; height: 132px; pointer-events: auto; touch-action: none; display: none; }
.stick-ring { position: absolute; inset: 0; border: 1px solid #c7d7c83d; border-radius: 50%; background: #111a1b66; box-shadow: inset 0 0 18px #0005; }
#stickThumb { position: absolute; left: 50%; top: 50%; width: 56px; height: 56px; margin: -28px; border: 1px solid #d8e6d681; border-radius: 50%; background: #a7b9aa50; box-shadow: 0 4px 12px #0006; }
#touchActions { position: absolute; right: max(18px, env(safe-area-inset-right)); bottom: max(22px, env(safe-area-inset-bottom)); width: 226px; height: 208px; pointer-events: none; display: none; }
button { appearance: none; border: 1px solid #b9c9b64d; border-radius: 5px; background: linear-gradient(180deg, #d6c28a, #a9925d); color: #101514; font-weight: 800; cursor: pointer; touch-action: manipulation; transition: filter .12s, transform .12s; }
button:hover { filter: brightness(1.08); } button:active { transform: scale(.96); }
.touch-button { position: absolute; pointer-events: auto; display: grid; place-items: center; width: 48px; height: 48px; padding: 0; border-radius: 50%; background: #14201dd9; border: 1px solid #d7e2d27d; color: #e4ede3; box-shadow: 0 4px 12px #0007; font-size: 22px; }
.touch-button.active { background: #b19d67; color: #111; }
#fireButton { right: 3px; bottom: 4px; width: 86px; height: 86px; border: 2px solid #e8c987; background: #8e342bcf; color: #fff1d2; font-size: 14px; letter-spacing: .08em; }
#weaponPrev { right: 158px; bottom: 81px; } #weaponNext { right: 103px; bottom: 112px; }
#inventoryButton { right: 104px; bottom: 57px; } #reloadButton { right: 55px; bottom: 115px; }
#crouchButton { right: 56px; bottom: 58px; } #jumpButton { right: 7px; bottom: 108px; }
.overlay { position: fixed; inset: 0; z-index: 5; display: flex; align-items: center; justify-content: center; padding: 20px; background: radial-gradient(ellipse at center, #101919bf, #050909e8); opacity: 1; transition: opacity .2s; pointer-events: auto; }
.overlay.hidden { display: none; opacity: 0; pointer-events: none; }
.title-panel { width: min(92vw, 500px); text-align: center; padding: clamp(24px, 5vw, 42px); }
.eyebrow { color: var(--gold) !important; font-size: 10px !important; letter-spacing: .16em; font-weight: 700; }
h1, h2 { margin: 0 0 16px; font-weight: 900; letter-spacing: .08em; line-height: 1.02; }
h1 { font-size: clamp(2.5rem, 9vw, 4.6rem); color: #e3e9dd; text-shadow: 0 4px 28px #849f7966; }
h2 { font-size: clamp(2rem, 7vw, 3.2rem); }
.title-panel p, .upgrade-panel > p { color: var(--muted); line-height: 1.55; margin: 0 0 20px; }
.title-panel button, .upgrade-panel > button { padding: 14px 24px; font-size: 12px; letter-spacing: .1em; }
.title-panel small { display: block; margin-top: 18px; color: #8d9993; font-size: 11px; }
.upgrade-panel { width: min(92vw, 680px); text-align: center; padding: 28px; }
.upgrade-choices { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin: 20px 0; }
.upgrade-choices button, .weapon-list button { display: flex; flex-direction: column; gap: 8px; min-height: 82px; justify-content: center; border: 1px solid var(--line); background: #111b1b; color: var(--ink); box-shadow: none; padding: 12px; }
.upgrade-choices button span { color: var(--muted); font-weight: 400; font-size: 12px; }
.secondary-button { background: transparent !important; border: 1px solid var(--line) !important; color: var(--muted) !important; box-shadow: none !important; }
.weapon-list { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; margin-bottom: 14px; }
.weapon-list button { min-height: 54px; }
@media (pointer: coarse) {
  #joystick, #touchActions { display: block; }
  #controlsHint { display: none; }
  #crosshair { opacity: .58; }
}
@media (max-width: 600px) {
  .topbar { gap: 6px; inset: max(9px, env(safe-area-inset-top)) 9px auto 9px; }
