const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
let targets;
for (let i = 0; i < 30; i++) {
  try { targets = await (await fetch('http://127.0.0.1:9228/json')).json(); break; } catch { await wait(200); }
}
if (!targets) throw new Error('Chrome remote debugging endpoint unavailable');
const target = targets.find((item) => item.type === 'page');
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.addEventListener('open', resolve, { once: true }); ws.addEventListener('error', reject, { once: true }); });
let id = 0;
const pending = new Map();
ws.addEventListener('message', (event) => {
  const data = JSON.parse(event.data);
  if (data.id && pending.has(data.id)) { pending.get(data.id)(data); pending.delete(data.id); }
});
function cdp(method, params = {}) {
  const commandId = ++id;
  return new Promise((resolve) => { pending.set(commandId, resolve); ws.send(JSON.stringify({ id: commandId, method, params })); });
}
async function evaluate(expression) {
  const result = await cdp('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  if (result.error || result.result?.exceptionDetails) throw new Error(JSON.stringify(result));
  return result.result?.result?.value;
}
await cdp('Page.enable');
await cdp('Runtime.enable');
await cdp('Page.navigate', { url: 'http://127.0.0.1:3000/' });
for (let i = 0; i < 40; i++) {
  await wait(200);
  if (await evaluate("document.querySelector('#gameCanvas')?.dataset.engine")) break;
}
await evaluate("document.querySelector('#startButton').click()");
await wait(1000);
const playing = await evaluate("({ time: document.querySelector('#timerText').textContent, wave: document.querySelector('#waveText').textContent, startHidden: document.querySelector('#startScreen').classList.contains('hidden') })");
await evaluate("document.querySelector('#pauseButton').click()");
const paused = await evaluate("({ visible: document.querySelector('#pauseScreen').classList.contains('visible'), label: document.querySelector('#pauseStats').textContent, time: document.querySelector('#timerText').textContent })");
await wait(600);
const pausedTime = await evaluate("document.querySelector('#timerText').textContent");
await evaluate("document.querySelector('#resumeButton').click()");
await wait(700);
const resumed = await evaluate("({ hidden: document.querySelector('#pauseScreen').classList.contains('hidden'), time: document.querySelector('#timerText').textContent })");
console.log(JSON.stringify({ playing, paused, pausedTime, resumed }, null, 2));
ws.close();
