function cdp(method, params = {}) { const n = ++id; return new Promise((resolve) => { pending.set(n, resolve); ws.send(JSON.stringify({ id: n, method, params })); }); }
async function evaluate(expression) { const result = await cdp('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true }); if (result.result?.exceptionDetails) throw new Error(JSON.stringify(result.result.exceptionDetails)); return result.result?.result?.value; }
await cdp('Page.enable'); await cdp('Runtime.enable');
